function decodeUTF16LE(buffer) {
  // Manual UTF-16-LE decode — works in ALL browsers including Safari
  const bytes = new Uint8Array(buffer);
  // Skip BOM prefix (first 5 bytes in this file format)
  let start = 0;
  if (bytes[0] === 0x20 || bytes[0] === 0x09 || bytes[0] === 0x0D) start = 5;
  else if (bytes[0] === 0xFF && bytes[1] === 0xFE) start = 2;
  let result = "";
  for (let i = start; i + 1 < bytes.length; i += 2) {
    const code = bytes[i] | (bytes[i + 1] << 8);
    result += String.fromCharCode(code);
  }
  return result;
}

function parseXLS(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        let text;
        try {
          // Try native TextDecoder first
          text = new TextDecoder("utf-16-le").decode(new Uint8Array(e.target.result).slice(5));
        } catch (_) {
          // Fallback: manual decode
          text = decodeUTF16LE(e.target.result);
        }
        const lines = text.split(/\r?\n/).filter(l => l.trim());
        if (lines.length < 2) return reject(new Error("الملف فارغ"));
        const headers = lines[0].split("\t").map(h => h.trim().replace(/^\uFEFF/, ""));
        const rows = lines.slice(1).filter(l => l.trim()).map(line => {
          const v = line.split("\t");
          const o = {}; headers.forEach((h, i) => o[h] = v[i] || ""); return o;
        });
        const n = v => parseFloat(v) || 0;
        const regMap = {}, dcMap = {}, hoMap = {};
        const DC_FILTER = ["Compass Risk Support Services", "Matrix Debt Collection", "National Center"];
        const HO_FILTER = ["Legal- DR. Sarhaan", "Documentation legal"];
        const HO_LABELS = { "Legal- DR. Sarhaan": "Legal - DR. Sarhaan", "Documentation legal ": "Documentation Legal", "Documentation legal": "Documentation Legal" };
        const REG_AR = {
          "Dhofar": "ظفار", "Dhofar ": "ظفار",
          "Musandam, Al Burimai and Al Dahirah": "مسندم، البريمي والظاهرة",
          "MUSCAT AND AL DAKHILIYAH": "مسقط والداخلية",
          "North and South Al Shaurqiah and Al Wasatah": "الشرقية الشمالية والجنوبية والوسطى",
          "South and North Al Batinah": "الباطنة الشمالية والجنوبية"
        };
        rows.forEach(row => {
          const region = (row["Region"] || "").trim();
          const paid = n(row["Paid Amount"]);
          const adj  = n(row["Adjustment"]);
          const col  = (row["Collector"] || "").trim();
          const branch = (row["Branch"] || "").trim();
          if (region === "Debt Collection Company") {
            const match = DC_FILTER.find(d => branch.includes(d.split(" ")[0]));
            if (match) {
              if (!dcMap[match]) dcMap[match] = { paid: 0, adj: 0 };
              dcMap[match].paid += paid; dcMap[match].adj += adj;
            }
          } else if (region === "Head Office") {
            const match = HO_FILTER.find(h => col.toLowerCase().includes(h.toLowerCase().split(" ")[0]));
            const key = HO_LABELS[col] || (col.toLowerCase().includes("legal") && col.toLowerCase().includes("dr") ? "Legal - DR. Sarhaan" : col.toLowerCase().includes("doc") ? "Documentation Legal" : null);
            if (key) {
              if (!hoMap[key]) hoMap[key] = { paid: 0, adj: 0 };
              hoMap[key].paid += paid; hoMap[key].adj += adj;
            }
          } else if (REG_AR[region]) {
            if (!regMap[region]) regMap[region] = { paid: 0, adj: 0, cMap: {} };
            regMap[region].paid += paid; regMap[region].adj += adj;
            if (col) {
              if (!regMap[region].cMap[col]) regMap[region].cMap[col] = { paid: 0, adj: 0 };
              regMap[region].cMap[col].paid += paid; regMap[region].cMap[col].adj += adj;
            }
          }
        });
        const REG_ORDER = ["Dhofar ","Dhofar","Musandam, Al Burimai and Al Dahirah","MUSCAT AND AL DAKHILIYAH","North and South Al Shaurqiah and Al Wasatah","South and North Al Batinah"];
        const regions = REG_ORDER.filter(k => regMap[k]).map((k,i) => ({
          id: k.toLowerCase().replace(/\s+/g,"_").replace(/[,]/g,""),
          nameAr: REG_AR[k], nameEn: k.trim(),
          paid: regMap[k].paid, adj: regMap[k].adj,
          collectors: Object.entries(regMap[k].cMap)
            .map(([nm,d]) => ({name: nm, paid: d.paid, adj: d.adj}))
            .sort((a,b) => (b.paid+b.adj)-(a.paid+a.adj))
        }));
        const debtCompanies = DC_FILTER.map(nm => dcMap[nm] ? {name: nm, ...dcMap[nm]} : {name: nm, paid:0, adj:0});
        const headOffice = ["Legal - DR. Sarhaan","Documentation Legal"].map(nm => hoMap[nm] ? {name:nm,...hoMap[nm]}:{name:nm,paid:0,adj:0});
        resolve({ uploadDate: new Date().toISOString().split("T")[0], totalRecords: rows.length, regions, debtCompanies, headOffice });
      } catch(err) { reject(err); }
    };
    reader.onerror = () => reject(new Error("فشل قراءة الملف"));
    reader.readAsArrayBuffer(file);
  });
}



const omr = n => new Intl.NumberFormat("en-US",{minimumFractionDigits:3,maximumFractionDigits:3}).format(n||0);

// ── Clock ────────────────────────────────────────────────────────────────────
function Clock() {
  const [t, setT] = useState(new Date());
  useEffect(()=>{const id=setInterval(()=>setT(new Date()),1000);return()=>clearInterval(id);},[]);
  const hh = String(t.getHours()).padStart(2,'0');
  const mm = String(t.getMinutes()).padStart(2,'0');
  const ss = String(t.getSeconds()).padStart(2,'0');
  const days = ['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
  const months = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
  const dateStr = `${days[t.getDay()]} ${t.getDate()} ${months[t.getMonth()]} ${t.getFullYear()}`;
  return (
    <div style={{textAlign:"right",lineHeight:1.3}}>
      <div style={{fontSize:26,fontWeight:800,color:"#e85d20",letterSpacing:2,fontVariantNumeric:"tabular-nums"}}>{hh}:{mm}:{ss}</div>
      <div style={{fontSize:11,color:"#999",marginTop:1}}>{dateStr}</div>
    </div>
  );
}

// ── Upload ───────────────────────────────────────────────────────────────────
function UploadBtn({onFile,uploading,success,error}) {
  const ref = useRef(null);
  return (
    <div
      onClick={()=>!uploading&&ref.current?.click()}
      onDrop={e=>{e.preventDefault();const f=e.dataTransfer.files?.[0];if(f)onFile(f);}}
      onDragOver={e=>e.preventDefault()}
      style={{
        border:`2px dashed ${success?"#22c55e":uploading?"#e85d20":"#f0d0c0"}`,
        borderRadius:12,padding:"10px 20px",cursor:uploading?"default":"pointer",
        background:success?"#f0fdf4":uploading?"#fff7f3":"#fff8f5",
        textAlign:"center",minWidth:180,transition:"all 0.3s",
      }}
    >
      <input ref={ref} type="file" accept=".xls,.xlsx" style={{display:"none"}} onChange={e=>{const f=e.target.files?.[0];if(f)onFile(f);e.target.value="";}}/>
      {uploading
        ? <div style={{color:"#e85d20",fontSize:13,fontWeight:700}}>⏳ جاري التحليل...</div>
        : success
        ? <div style={{color:"#16a34a",fontSize:13,fontWeight:700}}>✅ تم التحديث بنجاح</div>
        : <>
            <div style={{fontSize:22,marginBottom:2}}>📂</div>
            <div style={{fontSize:12,color:"#e85d20",fontWeight:700}}>رفع ملف يومي</div>
            <div style={{fontSize:10,color:"#bbb",marginTop:2}}>يستبدل البيانات تلقائياً</div>
          </>
      }
      {error && <div style={{color:"#dc2626",fontSize:10,marginTop:4,fontWeight:600}}>⚠ {error}</div>}
    </div>
  );
}

